SELECT s1.`c0` AS `s`, s1.`c1` AS `a` FROM (SELECT s5.`g0` AS `c0`, CAST(SUM(CAST(s5.`m0` AS DECIMAL(38,0)))  div COUNT(s5.`m0`)  AS BIGINT) AS `c1` FROM (SELECT s2.`c0` AS `g0`, s2.`c1` AS `m0` FROM (SELECT s3.`c7` AS `c0`, s3.`c8` AS `c1` FROM (SELECT s4.`c0` AS `c0`, s4.`c1` AS `c1`, s4.`c2` AS `c2`, s4.`c3` AS `c3`, s4.`c4` AS `c4`, s4.`c5` AS `c5`, s4.`c6` AS `c6`, s4.`c4` AS `c7`, s4.`c3` AS `c8` FROM (SELECT `d` AS `c0`, `d2` AS `c1`, `ts` AS `c2`, `x` AS `c3`, `s` AS `c4`, `ok` AS `c5`, (`v` + CAST('0' AS DOUBLE)) AS `c6` FROM `events`) AS s4) AS s3) AS s2) AS s5 GROUP BY s5.`g0`) AS s1
